    };

    // Create our terminal grid with the initial size
    const app_mailbox: App.Mailbox = .{ .rt_app = rt_app, .mailbox = &app.mailbox };
    var renderer_impl = renderer: {
        // Renderer.init takes ownership of the config only on success, after
        // which the errdefer below frees it, so this errdefer must end here.
        var renderer_config = try Renderer.DerivedConfig.init(alloc, config);
        errdefer renderer_config.deinit();

        break :renderer try Renderer.init(alloc, .{
            .device = render_device,
            .config = renderer_config,
            .font_grid = font_grid,
            .size = size,
            .surface_mailbox = .{ .surface = self, .app = app_mailbox },
            .rt_surface = rt_surface,
            .thread = &self.renderer_thread,
        });
    };
    errdefer renderer_impl.deinit();

    // The mutex used to protect our renderer state.
    const mutex = try alloc.create(std.Io.Mutex);
    mutex.* = .init;
    errdefer alloc.destroy(mutex);

    // Create the renderer thread
    var render_thread = try rendererpkg.Thread.init(
        alloc,
        config,
        rt_surface,
        &self.renderer,
        &self.renderer_state,
    );
    errdefer render_thread.deinit();

    // Create the IO thread
    var io_thread = try termio.Thread.init(alloc);
    errdefer io_thread.deinit();

    self.* = .{
        .id = id: {
            while (true) {
                const candidate = candidate: {
                    const rng_impl: std.Random.IoSource = .{ .io = global.io() };
                    const rng = rng_impl.interface();
                    break :candidate rng.int(u64);
                };
                if (candidate == 0) continue;
                break :id candidate;
            }
        },
        .alloc = alloc,
        .app = app,
        .rt_app = rt_app,
        .rt_surface = rt_surface,
        .font_grid_key = font_grid_key,
        .font_size = font_size,
        .font_size_adjusted = false,
        .font_metrics = font_grid.metrics,
        .renderer = renderer_impl,
        .renderer_thread = render_thread,
        .renderer_state = .{
            .mutex = mutex,
            .terminal = &self.io.terminal,
        },
        .renderer_thr = undefined,
        .mouse = .{},
        .keyboard = .{},
        .io = undefined,
        .io_thread = io_thread,
        .io_thr = undefined,
        .size = size,
        .config = derived_config,

        // Our conditional state is initialized to the app state. This
        // lets us get the most likely correct color theme and so on.
        .config_conditional_state = app.config_conditional_state,
    };

    // The command we're going to execute
    const command: ?configpkg.Command = command: {
        if (app.first) {
            if (config.@"initial-command") |command| {
                break :command command;
            }
        }
        break :command config.command;
    };

    // Start our IO implementation
    // This separate block ({}) is important because our errdefers must
    // be scoped here to be valid.
    {
        // Exec.init takes ownership of the env even if it fails, so the
        // errdefer for it must not reach past the call.
        const env = termio_env: {
            var env = rt_surface.defaultTermioEnv() catch |err| env: {
                // If an error occurs, we don't want to block surface startup.
                log.warn("error getting env map for surface err={}", .{err});
                break :env global.environMap() catch std.process.Environ.Map.init(alloc);
            };
            errdefer env.deinit();

            // don't leak GHOSTTY_LOG to any subprocesses
            _ = env.orderedRemove("GHOSTTY_LOG");

            var buf: [18]u8 = undefined;
            try env.put(
                "GHOSTTY_SURFACE_ID",
                std.mem.print(&buf, "0x{x:0>16}", .{self.id}) catch unreachable,
            );

            break :termio_env env;
        };

        // Initialize our IO backend
        var io_exec = try termio.Exec.init(alloc, .{
            .command = command,
            .env = env,
            .env_override = config.env,
            .shell_integration = config.@"shell-integration",
            .shell_integration_features = config.@"shell-integration-features",
            .cursor_blink = config.@"cursor-style-blink",
            .working_directory = if (config.@"working-directory") |wd| wd.value() else null,
            .resources_dir = global.resourcesDir().host(),
            .term = config.term,
            .rt_pre_exec_info = .init(config),
            .rt_post_fork_info = .init(config),
        });
        errdefer io_exec.deinit();

